PLAN = json.loads('{"admission_primary": 0.604, "blend": {"aggregations": [{"method": "rank_average", "scope": "per_user"}, {"method": "rank_average", "scope": "global"}], "weights": "equal"}, "full_member_limit": 3, "members": [{"config": {}, "family": "regularized-dcn-package", "member_id": "regularized-dcn-package", "script_source": "logs/run_farm_f7/nodes/001.py", "seed": 42}, {"code": "import argparse\\nimport csv\\nimport json\\nimport os\\nimport sys\\n\\nimport numpy as np\\nimport torch\\n\\nsys.path.insert(0, os.path.dirname(os.path.dirname(os.path.abspath(__file__))))\\nfrom data.official.evaluate import evaluate\\n\\n\\ndef load_data(data_dir):\\n    tp = os.path.join(data_dir, \'train.npz\')\\n    vp = os.path.join(data_dir, \'val.npz\')\\n    if os.path.exists(tp) and os.path.exists(vp):\\n        tr = dict(np.load(tp))\\n        va = dict(np.load(vp))\\n        return tr, va\\n    with open(os.path.join(data_dir, \'train.csv\'), newline=\'\') as f:\\n        trr = list(csv.DictReader(f))\\n    with open(os.path.join(data_dir, \'val.csv\'), newline=\'\') as f:\\n        var = list(csv.DictReader(f))\\n    fields = [\'user_id\', \'video_id\', \'author_id\', \'tab\']\\n    maps = []\\n    dims = []\\n    for field in fields:\\n        vals = [r.get(field, r[\'video_id\'] if field == \'author_id\' else \'\') for r in trr]\\n        mp = {v: i for i, v in enumerate(sorted(set(vals)))}\\n        maps.append(mp)\\n        dims.append(len(mp) + 1)\\n    durations = np.asarray([float(r[\'duration_ms\']) for r in trr])\\n    cuts = np.unique(np.quantile(durations, np.arange(1, 10) / 10.0))\\n    dims.append(len(cuts) + 1)\\n    offsets = np.cumsum([0] + dims[:-1])\\n    def encode(rows, train):\\n        X = np.empty((len(rows), 5), dtype=np.int32)\\n        for j, field in enumerate(fields):\\n            vals = [r.get(field, r[\'video_id\'] if field == \'author_id\' else \'\') for r in rows]\\n            X[:, j] = np.asarray([maps[j].get(v, dims[j] - 1) for v in vals]) + offsets[j]\\n        X[:, 4] = np.searchsorted(cuts, [float(r[\'duration_ms\']) for r in rows], side=\'right\') + offsets[4]\\n        return {\'X\': X, \'y\': np.asarray([float(r[\'long_view\']) for r in rows], dtype=np.float32), \'user\': np.asarray([r[\'user_id\'] for r in rows]), \'date\': np.asarray([r[\'date\'] for r in rows]), \'hourmin\': np.asarray([int(r[\'hourmin\']) for r in rows]), \'field_dims\': np.asarray(dims, dtype=np.int64), \'video_raw\': np.asarray([r[\'video_id\'] for r in rows])}\\n    return encode(trr, True), encode(var, False)\\n\\n\\ndef metric_values(m):\\n    return float(m.get(\'GAUC\', m.get(\'gauc\'))), float(m.get(\'nDCG@5\', m.get(\'ndcg5\'))), float(m[\'primary\'])\\n\\n\\ndef add_history(tr, va):\\n    dims = np.asarray(tr[\'field_dims\'], dtype=np.int64)\\n    video_offset = int(dims[0])\\n    video_dim = int(dims[1])\\n    base = int(dims.sum())\\n    tx = np.asarray(tr[\'X\'], dtype=np.int64)\\n    vx = np.asarray(va[\'X\'], dtype=np.int64)\\n    tu = np.asarray(tr[\'user\']).astype(str)\\n    vu = np.asarray(va[\'user\']).astype(str)\\n    local_video = tx[:, 1] - video_offset\\n    prev = np.full(len(tx), video_dim, dtype=np.int64)\\n    last = {}\\n    for i in range(len(tx)):\\n        u = tu[i]\\n        if u in last:\\n            prev[i] = last[u]\\n        last[u] = int(local_video[i])\\n    vprev = np.asarray([last.get(u, video_dim) for u in vu], dtype=np.int64)\\n    tx = np.column_stack([tx, base + prev])\\n    vx = np.column_stack([vx, base + vprev])\\n    return tx, vx, base + video_dim + 1\\n\\n\\nclass DeepFM(torch.nn.Module):\\n    def __init__(self, total, fields=6, k=16):\\n        super().__init__()\\n        self.emb = torch.nn.Embedding(total, k)\\n        self.lin = torch.nn.Embedding(total, 1)\\n        self.bias = torch.nn.Parameter(torch.zeros(1))\\n        self.drop = torch.nn.Dropout(0.22)\\n        self.mlp = torch.nn.Sequential(torch.nn.Linear(fields * k, 128), torch.nn.ReLU(), torch.nn.Dropout(0.22), torch.nn.Linear(128, 64), torch.nn.ReLU(), torch.nn.Dropout(0.22), torch.nn.Linear(64, 1))\\n        torch.nn.init.normal_(self.emb.weight, std=0.01)\\n        torch.nn.init.zeros_(self.lin.weight)\\n        for m in self.mlp:\\n            if isinstance(m, torch.nn.Linear):\\n                torch.nn.init.xavier_uniform_(m.weight)\\n                torch.nn.init.zeros_(m.bias)\\n    def forward(self, x):\\n        e = self.drop(self.emb(x))\\n        s = e.sum(1)\\n        fm = 0.5 * (s.square() - e.square().sum(1)).sum(1)\\n        return self.bias + self.lin(x).sum((1, 2)) + fm + self.mlp(e.reshape(len(x), -1)).squeeze(1)\\n\\n\\ndef predict(model, X, device):\\n    model.eval()\\n    out = []\\n    with torch.no_grad():\\n        for s in range(0, len(X), 65536):\\n            out.append(model(X[s:s + 65536].to(device)).cpu().numpy())\\n    return np.concatenate(out).astype(np.float64)\\n\\n\\ndef main():\\n    p = argparse.ArgumentParser()\\n    p.add_argument(\'--data-dir\', required=True)\\n    p.add_argument(\'--out-dir\', required=True)\\n    p.add_argument(\'--seed\', type=int, default=42)\\n    p.add_argument(\'--epochs\', type=int, default=12)\\n    a = p.parse_args()\\n    os.makedirs(a.out_dir, exist_ok=True)\\n    smoke = os.environ.get(\'SMOKE_EPOCHS\')\\n    epochs = min(a.epochs, int(smoke)) if smoke is not None else a.epochs\\n    np.random.seed(a.seed)\\n    torch.manual_seed(a.seed)\\n    device = torch.device(\'cuda\' if torch.cuda.is_available() else \'cpu\')\\n    if device.type == \'cuda\':\\n        torch.cuda.manual_seed_all(a.seed)\\n        torch.backends.cudnn.deterministic = True\\n        torch.backends.cudnn.benchmark = False\\n    tr, va = load_data(a.data_dir)\\n    tx, vx, total = add_history(tr, va)\\n    Xt = torch.from_numpy(tx).long()\\n    Xv = torch.from_numpy(vx).long()\\n    yt = torch.from_numpy(np.asarray(tr[\'y\'], dtype=np.float32))\\n    vu = np.asarray(va[\'user\'])\\n    vy = np.asarray(va[\'y\']).astype(int)\\n    model = DeepFM(total).to(device)\\n    opt = torch.optim.AdamW(model.parameters(), lr=8e-4, weight_decay=3e-4)\\n    rng = np.random.RandomState(a.seed)\\n    best = -1.0\\n    best_scores = None\\n    trace = []\\n    for epoch in range(epochs):\\n        model.train()\\n        perm = rng.permutation(len(Xt))\\n        loss_value = 0.0\\n        for s in range(0, len(Xt), 16384):\\n            idx = torch.from_numpy(perm[s:s + 16384]).long()\\n            xb = Xt[idx].to(device)\\n            yb = yt[idx].to(device)\\n            loss = torch.nn.functional.binary_cross_entropy_with_logits(model(xb), yb)\\n            opt.zero_grad(set_to_none=True)\\n            loss.backward()\\n            torch.nn.utils.clip_grad_norm_(model.parameters(), 5.0)\\n            opt.step()\\n            loss_value = float(loss.detach().cpu())\\n        for pg in opt.param_groups:\\n            pg[\'lr\'] *= 0.55\\n        scores = predict(model, Xv, device)\\n        g, n, primary = metric_values(evaluate(vu, vy, scores))\\n        trace.append({\'epoch\': epoch + 1, \'train_loss\': loss_value, \'gauc\': g, \'ndcg5\': n, \'primary\': primary})\\n        if primary > best:\\n            best = primary\\n            best_scores = scores.copy()\\n    g, n, primary = metric_values(evaluate(vu, vy, best_scores))\\n    with open(os.path.join(a.out_dir, \'progress.log\'), \'a\') as f:\\n        f.write(json.dumps({\'family\': \'seq-history-deepfm\', \'seed\': a.seed, \'primary\': primary}) + \'\\\\n\')\\n    with open(os.path.join(a.out_dir, \'metrics.json\'), \'w\') as f:\\n        json.dump({\'gauc\': g, \'ndcg5\': n, \'primary\': primary, \'history\': trace}, f)\\n    video_offset = int(np.asarray(tr[\'field_dims\'])[0])\\n    vids = np.asarray(va[\'X\'])[:, 1].astype(np.int64) - video_offset\\n    with open(os.path.join(a.out_dir, \'predictions.csv\'), \'w\') as f:\\n        f.write(\'row_id,user_id,video_id,score\\\\n\')\\n        for i, score in enumerate(best_scores):\\n            f.write(f\'{i},{vu[i]},{vids[i]},{score:.9g}\\\\n\')\\n\\n\\nif __name__ == \'__main__\':\\n    main()\\n", "config": {}, "family": "seq-history-deepfm", "member_id": "seq-history-deepfm", "seed": 43}, {"code": "import argparse\\nimport csv\\nimport json\\nimport os\\nimport sys\\n\\nimport numpy as np\\nimport torch\\n\\nsys.path.insert(0, os.path.dirname(os.path.dirname(os.path.abspath(__file__))))\\nfrom data.official.evaluate import evaluate\\n\\n\\ndef load_data(data_dir):\\n    tp, vp = os.path.join(data_dir, \'train.npz\'), os.path.join(data_dir, \'val.npz\')\\n    if os.path.exists(tp) and os.path.exists(vp):\\n        return dict(np.load(tp)), dict(np.load(vp))\\n    with open(os.path.join(data_dir, \'train.csv\'), newline=\'\') as f:\\n        trr = list(csv.DictReader(f))\\n    with open(os.path.join(data_dir, \'val.csv\'), newline=\'\') as f:\\n        var = list(csv.DictReader(f))\\n    names = [\'user_id\', \'video_id\', \'author_id\', \'tab\']\\n    maps, dims = [], []\\n    for name in names:\\n        vals = [r.get(name, r[\'video_id\'] if name == \'author_id\' else \'\') for r in trr]\\n        mp = {v: i for i, v in enumerate(sorted(set(vals)))}\\n        maps.append(mp)\\n        dims.append(len(mp) + 1)\\n    duration = np.asarray([float(r[\'duration_ms\']) for r in trr])\\n    cuts = np.unique(np.quantile(duration, np.arange(1, 10) / 10.0))\\n    dims.append(len(cuts) + 1)\\n    offsets = np.cumsum([0] + dims[:-1])\\n    def enc(rows):\\n        X = np.empty((len(rows), 5), dtype=np.int32)\\n        for j, name in enumerate(names):\\n            vals = [r.get(name, r[\'video_id\'] if name == \'author_id\' else \'\') for r in rows]\\n            X[:, j] = [maps[j].get(v, dims[j] - 1) + offsets[j] for v in vals]\\n        X[:, 4] = np.searchsorted(cuts, [float(r[\'duration_ms\']) for r in rows], side=\'right\') + offsets[4]\\n        return {\'X\': X, \'y\': np.asarray([float(r[\'long_view\']) for r in rows], np.float32), \'user\': np.asarray([r[\'user_id\'] for r in rows]), \'date\': np.asarray([r[\'date\'] for r in rows]), \'hourmin\': np.asarray([int(r[\'hourmin\']) for r in rows]), \'field_dims\': np.asarray(dims)}\\n    return enc(trr), enc(var)\\n\\n\\ndef temporal(X, hourmin, date, total):\\n    hm = np.asarray(hourmin).astype(np.int64)\\n    hour = np.where(hm >= 100, hm // 100, hm // 60) % 24\\n    raw = np.asarray(date).astype(str)\\n    day = np.empty(len(raw), dtype=np.int64)\\n    for i, text in enumerate(raw):\\n        digits = \'\'.join(c for c in text if c.isdigit())[:8]\\n        day[i] = int(digits) % 7 if digits else 0\\n    return np.column_stack([X, total + hour, total + 24 + day]).astype(np.int64)\\n\\n\\ndef recency(date):\\n    vals = np.asarray(date).astype(str)\\n    uniq = {v: i for i, v in enumerate(sorted(set(vals)))}\\n    order = np.asarray([uniq[v] for v in vals], dtype=np.float32)\\n    w = np.power(0.5, (order.max() - order) / 7.0).astype(np.float32)\\n    return w / max(float(w.mean()), 1e-8)\\n\\n\\nclass TemporalDeepFM(torch.nn.Module):\\n    def __init__(self, total):\\n        super().__init__()\\n        self.emb = torch.nn.Embedding(total, 16)\\n        self.lin = torch.nn.Embedding(total, 1)\\n        self.bias = torch.nn.Parameter(torch.zeros(1))\\n        self.net = torch.nn.Sequential(torch.nn.Linear(112, 128), torch.nn.ReLU(), torch.nn.Dropout(0.28), torch.nn.Linear(128, 64), torch.nn.ReLU(), torch.nn.Dropout(0.28), torch.nn.Linear(64, 1))\\n        torch.nn.init.normal_(self.emb.weight, std=0.01)\\n        torch.nn.init.zeros_(self.lin.weight)\\n        for m in self.net:\\n            if isinstance(m, torch.nn.Linear):\\n                torch.nn.init.xavier_uniform_(m.weight)\\n                torch.nn.init.zeros_(m.bias)\\n    def forward(self, x):\\n        e = self.emb(x)\\n        s = e.sum(1)\\n        fm = 0.5 * (s.square() - e.square().sum(1)).sum(1)\\n        return self.bias + self.lin(x).sum((1, 2)) + fm + self.net(e.reshape(len(x), -1)).squeeze(1)\\n\\n\\ndef metric(m):\\n    return float(m.get(\'GAUC\', m.get(\'gauc\'))), float(m.get(\'nDCG@5\', m.get(\'ndcg5\'))), float(m[\'primary\'])\\n\\n\\ndef pred(model, X, device):\\n    model.eval()\\n    ans = []\\n    with torch.no_grad():\\n        for s in range(0, len(X), 65536):\\n            ans.append(model(X[s:s + 65536].to(device)).cpu().numpy())\\n    return np.concatenate(ans).astype(np.float64)\\n\\n\\ndef main():\\n    ap = argparse.ArgumentParser()\\n    ap.add_argument(\'--data-dir\', required=True)\\n    ap.add_argument(\'--out-dir\', required=True)\\n    ap.add_argument(\'--seed\', type=int, default=42)\\n    ap.add_argument(\'--epochs\', type=int, default=14)\\n    a = ap.parse_args()\\n    os.makedirs(a.out_dir, exist_ok=True)\\n    smoke = os.environ.get(\'SMOKE_EPOCHS\')\\n    epochs = min(a.epochs, int(smoke)) if smoke is not None else a.epochs\\n    np.random.seed(a.seed)\\n    torch.manual_seed(a.seed)\\n    device = torch.device(\'cuda\' if torch.cuda.is_available() else \'cpu\')\\n    if device.type == \'cuda\':\\n        torch.cuda.manual_seed_all(a.seed)\\n        torch.backends.cudnn.deterministic = True\\n        torch.backends.cudnn.benchmark = False\\n    tr, va = load_data(a.data_dir)\\n    base = int(np.asarray(tr[\'field_dims\']).sum())\\n    Xt = torch.from_numpy(temporal(np.asarray(tr[\'X\']), tr[\'hourmin\'], tr[\'date\'], base)).long()\\n    Xv = torch.from_numpy(temporal(np.asarray(va[\'X\']), va[\'hourmin\'], va[\'date\'], base)).long()\\n    yt = torch.from_numpy(np.asarray(tr[\'y\'], dtype=np.float32))\\n    wt = torch.from_numpy(recency(tr[\'date\']))\\n    vu, vy = np.asarray(va[\'user\']), np.asarray(va[\'y\']).astype(int)\\n    model = TemporalDeepFM(base + 31).to(device)\\n    opt = torch.optim.AdamW(model.parameters(), lr=7e-4, weight_decay=6e-4)\\n    rng = np.random.RandomState(a.seed)\\n    best, best_scores, trace = -1.0, None, []\\n    for epoch in range(epochs):\\n        model.train()\\n        perm = rng.permutation(len(Xt))\\n        lv = 0.0\\n        for s in range(0, len(Xt), 16384):\\n            idx = torch.from_numpy(perm[s:s + 16384]).long()\\n            logits = model(Xt[idx].to(device))\\n            each = torch.nn.functional.binary_cross_entropy_with_logits(logits, yt[idx].to(device), reduction=\'none\')\\n            wb = wt[idx].to(device)\\n            loss = (each * wb).sum() / wb.sum().clamp_min(1e-6)\\n            opt.zero_grad(set_to_none=True)\\n            loss.backward()\\n            torch.nn.utils.clip_grad_norm_(model.parameters(), 5.0)\\n            opt.step()\\n            lv = float(loss.detach().cpu())\\n        if epoch in (1, 3, 5):\\n            for pg in opt.param_groups:\\n                pg[\'lr\'] *= 0.38\\n        scores = pred(model, Xv, device)\\n        g, n, pr = metric(evaluate(vu, vy, scores))\\n        trace.append({\'epoch\': epoch + 1, \'train_loss\': lv, \'gauc\': g, \'ndcg5\': n, \'primary\': pr})\\n        if pr > best:\\n            best, best_scores = pr, scores.copy()\\n    g, n, pr = metric(evaluate(vu, vy, best_scores))\\n    with open(os.path.join(a.out_dir, \'progress.log\'), \'a\') as f:\\n        f.write(json.dumps({\'family\': \'temporal-context-deepfm\', \'seed\': a.seed, \'primary\': pr}) + \'\\\\n\')\\n    with open(os.path.join(a.out_dir, \'metrics.json\'), \'w\') as f:\\n        json.dump({\'gauc\': g, \'ndcg5\': n, \'primary\': pr, \'history\': trace}, f)\\n    video_offset = int(np.asarray(tr[\'field_dims\'])[0])\\n    vids = np.asarray(va[\'X\'])[:, 1].astype(np.int64) - video_offset\\n    with open(os.path.join(a.out_dir, \'predictions.csv\'), \'w\') as f:\\n        f.write(\'row_id,user_id,video_id,score\\\\n\')\\n        for i, score in enumerate(best_scores):\\n            f.write(f\'{i},{vu[i]},{vids[i]},{score:.9g}\\\\n\')\\n\\n\\nif __name__ == \'__main__\':\\n    main()\\n", "config": {}, "family": "temporal-context-deepfm", "member_id": "temporal-context-deepfm", "seed": 44}, {"code": "import argparse\\nimport csv\\nimport json\\nimport os\\nimport sys\\n\\nimport numpy as np\\nimport torch\\n\\nsys.path.insert(0, os.path.dirname(os.path.dirname(os.path.abspath(__file__))))\\nfrom data.official.evaluate import evaluate\\n\\n\\ndef load_data(data_dir):\\n    tp, vp = os.path.join(data_dir, \'train.npz\'), os.path.join(data_dir, \'val.npz\')\\n    if os.path.exists(tp) and os.path.exists(vp):\\n        return dict(np.load(tp)), dict(np.load(vp))\\n    with open(os.path.join(data_dir, \'train.csv\'), newline=\'\') as f:\\n        trr = list(csv.DictReader(f))\\n    with open(os.path.join(data_dir, \'val.csv\'), newline=\'\') as f:\\n        var = list(csv.DictReader(f))\\n    names = [\'user_id\', \'video_id\', \'author_id\', \'tab\']\\n    maps, dims = [], []\\n    for name in names:\\n        vals = [r.get(name, r[\'video_id\'] if name == \'author_id\' else \'\') for r in trr]\\n        mp = {v: i for i, v in enumerate(sorted(set(vals)))}\\n        maps.append(mp)\\n        dims.append(len(mp) + 1)\\n    dur = np.asarray([float(r[\'duration_ms\']) for r in trr])\\n    cuts = np.unique(np.quantile(dur, np.arange(1, 10) / 10.0))\\n    dims.append(len(cuts) + 1)\\n    offsets = np.cumsum([0] + dims[:-1])\\n    def enc(rows):\\n        X = np.empty((len(rows), 5), dtype=np.int32)\\n        for j, name in enumerate(names):\\n            vals = [r.get(name, r[\'video_id\'] if name == \'author_id\' else \'\') for r in rows]\\n            X[:, j] = [maps[j].get(v, dims[j] - 1) + offsets[j] for v in vals]\\n        X[:, 4] = np.searchsorted(cuts, [float(r[\'duration_ms\']) for r in rows], side=\'right\') + offsets[4]\\n        return {\'X\': X, \'y\': np.asarray([float(r[\'long_view\']) for r in rows], dtype=np.float32), \'user\': np.asarray([r[\'user_id\'] for r in rows]), \'field_dims\': np.asarray(dims)}\\n    return enc(trr), enc(var)\\n\\n\\nclass GaugeFixedInteraction(torch.nn.Module):\\n    def __init__(self, total, k=16):\\n        super().__init__()\\n        self.emb = torch.nn.Embedding(total, k)\\n        self.item_linear = torch.nn.Embedding(total, 1)\\n        self.bias = torch.nn.Parameter(torch.zeros(1))\\n        self.pair_weight = torch.nn.Parameter(torch.ones(10))\\n        self.head = torch.nn.Sequential(torch.nn.Linear(10, 32), torch.nn.ReLU(), torch.nn.Dropout(0.18), torch.nn.Linear(32, 1))\\n        torch.nn.init.normal_(self.emb.weight, std=0.01)\\n        torch.nn.init.zeros_(self.item_linear.weight)\\n    def forward(self, x):\\n        e = self.emb(x)\\n        interactions = []\\n        for i in range(5):\\n            for j in range(i + 1, 5):\\n                interactions.append((e[:, i] * e[:, j]).sum(1))\\n        z = torch.stack(interactions, 1)\\n        # Excluding the user-field linear term fixes the user-constant logit gauge.\\n        linear = self.item_linear(x[:, 1:]).sum((1, 2))\\n        return self.bias + linear + (z * self.pair_weight).sum(1) + self.head(z).squeeze(1)\\n\\n\\ndef metric(m):\\n    return float(m.get(\'GAUC\', m.get(\'gauc\'))), float(m.get(\'nDCG@5\', m.get(\'ndcg5\'))), float(m[\'primary\'])\\n\\n\\ndef predict(model, X, device):\\n    model.eval()\\n    out = []\\n    with torch.no_grad():\\n        for s in range(0, len(X), 65536):\\n            out.append(model(X[s:s + 65536].to(device)).cpu().numpy())\\n    return np.concatenate(out).astype(np.float64)\\n\\n\\ndef main():\\n    p = argparse.ArgumentParser()\\n    p.add_argument(\'--data-dir\', required=True)\\n    p.add_argument(\'--out-dir\', required=True)\\n    p.add_argument(\'--seed\', type=int, default=42)\\n    p.add_argument(\'--epochs\', type=int, default=16)\\n    a = p.parse_args()\\n    os.makedirs(a.out_dir, exist_ok=True)\\n    smoke = os.environ.get(\'SMOKE_EPOCHS\')\\n    epochs = min(a.epochs, int(smoke)) if smoke is not None else a.epochs\\n    np.random.seed(a.seed)\\n    torch.manual_seed(a.seed)\\n    device = torch.device(\'cuda\' if torch.cuda.is_available() else \'cpu\')\\n    if device.type == \'cuda\':\\n        torch.cuda.manual_seed_all(a.seed)\\n        torch.backends.cudnn.deterministic = True\\n        torch.backends.cudnn.benchmark = False\\n    tr, va = load_data(a.data_dir)\\n    Xt = torch.from_numpy(np.asarray(tr[\'X\'], dtype=np.int64))\\n    Xv = torch.from_numpy(np.asarray(va[\'X\'], dtype=np.int64))\\n    yt = torch.from_numpy(np.asarray(tr[\'y\'], dtype=np.float32))\\n    vu, vy = np.asarray(va[\'user\']), np.asarray(va[\'y\']).astype(int)\\n    model = GaugeFixedInteraction(int(np.asarray(tr[\'field_dims\']).sum())).to(device)\\n    opt = torch.optim.AdamW(model.parameters(), lr=9e-4, weight_decay=2e-4)\\n    rng = np.random.RandomState(a.seed)\\n    best, best_scores, trace = -1.0, None, []\\n    smooth = 0.025\\n    for epoch in range(epochs):\\n        model.train()\\n        perm = rng.permutation(len(Xt))\\n        lv = 0.0\\n        for s in range(0, len(Xt), 16384):\\n            idx = torch.from_numpy(perm[s:s + 16384]).long()\\n            target = yt[idx].to(device) * (1.0 - 2.0 * smooth) + smooth\\n            loss = torch.nn.functional.binary_cross_entropy_with_logits(model(Xt[idx].to(device)), target)\\n            opt.zero_grad(set_to_none=True)\\n            loss.backward()\\n            torch.nn.utils.clip_grad_norm_(model.parameters(), 5.0)\\n            opt.step()\\n            lv = float(loss.detach().cpu())\\n        if epoch in (1, 2, 4):\\n            for pg in opt.param_groups:\\n                pg[\'lr\'] *= 0.5\\n        scores = predict(model, Xv, device)\\n        g, n, pr = metric(evaluate(vu, vy, scores))\\n        trace.append({\'epoch\': epoch + 1, \'train_loss\': lv, \'gauc\': g, \'ndcg5\': n, \'primary\': pr})\\n        if pr > best:\\n            best, best_scores = pr, scores.copy()\\n    g, n, pr = metric(evaluate(vu, vy, best_scores))\\n    with open(os.path.join(a.out_dir, \'progress.log\'), \'a\') as f:\\n        f.write(json.dumps({\'family\': \'gauge-fixed-bce\', \'seed\': a.seed, \'primary\': pr}) + \'\\\\n\')\\n    with open(os.path.join(a.out_dir, \'metrics.json\'), \'w\') as f:\\n        json.dump({\'gauc\': g, \'ndcg5\': n, \'primary\': pr, \'history\': trace}, f)\\n    video_offset = int(np.asarray(tr[\'field_dims\'])[0])\\n    vids = np.asarray(va[\'X\'])[:, 1].astype(np.int64) - video_offset\\n    with open(os.path.join(a.out_dir, \'predictions.csv\'), \'w\') as f:\\n        f.write(\'row_id,user_id,video_id,score\\\\n\')\\n        for i, score in enumerate(best_scores):\\n            f.write(f\'{i},{vu[i]},{vids[i]},{score:.9g}\\\\n\')\\n\\n\\nif __name__ == \'__main__\':\\n    main()\\n", "config": {}, "family": "gauge-fixed-bce", "member_id": "gauge-fixed-bce", "seed": 45}], "min_probe_blend_gain": 0.0, "probe_epochs": 2}')
